197	// DeleteAttachmentStorageWithInstanceSetting deletes attachment storage using a preloaded instance storage setting.
198	func (s *Store) DeleteAttachmentStorageWithInstanceSetting(ctx context.Context, attachment *Attachment, instanceStorageSetting *storepb.InstanceStorageSetting) error {
199		return s.deleteAttachmentStorageImpl(ctx, attachment, instanceStorageSetting)
200	}
