55	// DeleteIdentityProviderSafely validates and deletes an IdP as one serialized operation.
56	func (s *Store) DeleteIdentityProviderSafely(ctx context.Context, delete *DeleteIdentityProvider) error {
57		if delete == nil {
58			return errors.New("identity provider deletion is required")
59		}
60		mutation := &AuthenticationConfigMutation{
61			DeleteIdentityProviderID: &delete.ID,
62			Validate: func(state *AuthenticationConfigState) error {
63				return s.validateAuthenticationMutationState(state, nil, &delete.ID)
64			},
65		}
66		return s.applyAuthenticationConfigMutation(ctx, mutation)
67	}
